// Extended reproduction for ISSUE.md
const mri = require("../lib/index.js");

let pass = 0, fail = 0;
function check(name, cond, actual) {
  if (cond) { pass++; console.log(`PASS: ${name}`); }
  else { fail++; console.log(`FAIL: ${name}\n  actual:`, JSON.stringify(actual)); }
}

// 1. Original issue: -a 01 with string default and alias
let r = mri(["-a", "01"], {
  alias: { arg: "a" },
  default: { arg: "01" },
});
check("Issue case: -a 01 keeps string", r.a === "01" && typeof r.a === "string", r);
check("Issue case: arg also keeps string", r.arg === "01" && typeof r.arg === "string", r);

// 2. --arg 01 with string default and alias
r = mri(["--arg", "01"], {
  alias: { arg: "a" },
  default: { arg: "01" },
});
check("--arg 01 keeps string", r.arg === "01" && typeof r.arg === "string", r);
check("--arg 01 mirrors to a as string", r.a === "01" && typeof r.a === "string", r);

// 3. Default applied when arg not given
r = mri([], {
  alias: { arg: "a" },
  default: { arg: "hello" },
});
check("Default: arg", r.arg === "hello", r);
check("Default: a mirrors arg", r.a === "hello", r);

// 4. Multiple aliases
r = mri(["-b", "01"], {
  alias: { arg: ["a", "b"] },
  default: { arg: "01" },
});
check("Multiple aliases: -b 01 string", r.b === "01" && typeof r.b === "string", r);
check("Multiple aliases: arg", r.arg === "01" && typeof r.arg === "string", r);
check("Multiple aliases: a mirrors", r.a === "01", r);

// 5. Boolean default with alias
r = mri(["-v"], {
  alias: { verbose: "v" },
  default: { verbose: true },
});
check("Boolean default with alias", r.v === true && r.verbose === true, r);

// 6. Number default still coerces to number when used as number
r = mri(["-c", "5"], {
  alias: { count: "c" },
  default: { count: 0 },
});
check("Number default with alias still coerces 5 to number", r.c === 5 && typeof r.c === "number", r);

// 7. Existing test: alias mirrors
r = mri(["--foo", "bar"], { alias: { foo: "f" } });
check("Existing: alias mirrors", r.foo === "bar" && r.f === "bar", r);

// 8. Existing test: string opts
r = mri(["-s", "0001234"], { string: "s" });
check("Existing: string opts preserve leading zeros", r.s === "0001234" && typeof r.s === "string", r);

console.log(`\nSummary: ${pass} passed, ${fail} failed`);
process.exit(fail === 0 ? 0 : 1);

